import {cinematicItems,cinematicPrimary,remotePrewarmAllowed} from './cinematic-model.js?v=directorcinematic02';
// Preparation belongs to Direction; the existing inline cue owns presentation.
export function mountSceneCinematic(root,{scene,save,sequence,stop=()=>{},presentation=()=>({})}){
 const items=cinematicItems(scene);if(!items.length)return;
 const row=document.createElement('section');row.className='director-section scene-cinematic';row.setAttribute('aria-label','Cinematic da cena');
 const heading=document.createElement('h3');heading.textContent='Cinematic';
 const name=document.createElement(items.length>1?'select':'span');name.className='scene-cinematic-choice';
 if(items.length>1){name.setAttribute('aria-label','Cinematic principal da cena');const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='Escolha a principal';name.append(placeholder);for(const item of items){const option=document.createElement('option');option.value=item.id;option.textContent=item.name;name.append(option);}name.value=cinematicPrimary(scene)?.id||'';name.onchange=()=>{const prior=scene.cinematic.primaryId;if(name.value)scene.cinematic.primaryId=name.value;else delete scene.cinematic.primaryId;if(save()===false){if(prior===undefined)delete scene.cinematic.primaryId;else scene.cinematic.primaryId=prior;}refresh();};}
 else name.textContent=items[0].name;
 const status=document.createElement('small');status.id='sceneCinematicReadiness';status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const hint=document.createElement('p');hint.className='scene-cinematic-hint';hint.textContent='Dispare pela cue no roteiro. Crie ou edite em Ferramentas → Cinemática.';
 const end=document.createElement('button');end.id='stopCinematic';end.type='button';end.className='btn outline';end.textContent='Encerrar apresentação';end.onclick=stop;
 const permission=document.createElement('details');permission.className='scene-cinematic-permission';const summary=document.createElement('summary');summary.textContent='Opções de preparação';permission.append(summary);
 const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.setAttribute('aria-label','Autorizar preload remoto desta Cinematic');label.append(check,document.createTextNode(' Antecipar arquivos aos jogadores'));const help=document.createElement('small');help.textContent='A preparação local é automática. O envio antecipado revela os arquivos aos jogadores: autorize somente conteúdo liberado. Editar a composição revoga a autorização.';permission.append(label,help);
 const participants=document.createElement('ul');participants.className='scene-cinematic-participants';permission.append(participants);
 check.onchange=()=>{const item=cinematicPrimary(scene);if(!item)return;const prior=scene.cinematic.remotePrewarmIds;scene.cinematic.remotePrewarmIds=(scene.cinematic.remotePrewarmIds||[]).filter(id=>id!==item.id);if(check.checked)scene.cinematic.remotePrewarmIds.push(item.id);if(save()===false)scene.cinematic.remotePrewarmIds=prior;refresh();};
 function refresh(){const item=cinematicPrimary(scene),view=sequence.view(),live=presentation();check.disabled=!item;check.checked=remotePrewarmAllowed(scene,item);if(items.length>1)name.value=item?.id||'';status.textContent=item?view.status+(view.next?' · Próxima: '+view.next+' · '+view.nextStatus:''):'Escolha a principal para preparar.';status.title=view.error||'';end.hidden=!live.running;participants.replaceChildren();for(const peer of view.remote||[]){const li=document.createElement('li');li.textContent=peer.name+' · '+({ready:'Pronta',preparing:'Preparando',waiting:'Aguardando',failed:'Falha',unsupported:'Atualize o CRIS'}[peer.status]||'Aguardando');participants.append(li);}if(live.running&&live.message)status.title=live.message;}
 row.append(heading,name,status,hint,end,permission);root.append(row);refresh();return {update:refresh};
}
